'use strict';
// Student/admin screen renderers and content editor forms.
const title=()=>({welcome:'Welcome',onboarding:'Get started',games:'Games',game:'Let’s play',gameResult:'Game results',dashboard:role==='admin'?'Admin home':'Home',modules:'Learn',module:'Your lessons',lesson:'Lesson',phrasebook:'Words & phrases',reviews:'Practice',progress:'My progress',achievements:'Rewards',profile:'My profile',feedback:'Share feedback',users:'Student management',content:'Content studio',assessments:'Assessment studio',analytics:'Learning analytics',ml:'Adaptive insights',adminfeedback:'Student feedback',settings:'Learning settings',auth:'Welcome to MalayMate',placement:'Placement test',quiz:'Assessment',result:'Your results'}[view]||'MalayMate');
function navItem(v,label,i){return `<button class="nav-btn ${view===v||v==='modules'&&['module','lesson'].includes(view)?'active':''}" data-action="nav:${v}">${icon(i)}${label}${v==='reviews'&&recommendations().length?`<span class="pill gold" style="margin-left:auto;padding:1px 6px">${recommendations().length}</span>`:''}</button>`}
function art(){return `<svg viewBox="0 0 300 240" xmlns="http://www.w3.org/2000/svg" aria-label="Illustration of a phrase card, book and tropical leaves"><circle cx="170" cy="128" r="91" fill="#dce6c8"/><path d="M220 217c0-55 17-94 45-119-2 56-18 89-45 119" fill="#637d48"/><path d="M230 187c-30-22-39-43-36-69 27 24 37 45 36 69" fill="#a4b77c"/><path d="M250 147c8-24 18-37 36-44-1 22-14 38-36 44" fill="#94ab66"/><g transform="rotate(-9 117 153)"><rect x="45" y="114" width="145" height="94" rx="8" fill="#54723f"/><path d="M49 110c27-9 47-5 68 3 24-8 47-9 69-3v89c-24-7-47-9-69 0-24-9-46-7-68 0z" fill="#fffdf3"/><path d="M117 113v86" stroke="#d3d9bd" stroke-width="2"/><path d="M62 132h39 M62 143h39 M62 154h30 M132 132h38 M132 143h38 M132 154h29" stroke="#b6c59a" stroke-width="4" stroke-linecap="round"/></g><g transform="rotate(7 183 70)"><rect x="97" y="27" width="153" height="91" rx="14" fill="#fffefa" stroke="#b8c89e"/><path d="m127 113-7 20 28-18" fill="#fffefa" stroke="#b8c89e"/><text x="118" y="59" fill="#284b32" font-family="Arial" font-weight="700" font-size="17">Apa khabar?</text><text x="118" y="82" fill="#7e8b6d" font-family="Arial" font-size="10">How are you?</text><circle cx="226" cy="91" r="9" fill="#e0ebca"/><path d="m223 87 7 4-7 4z" fill="#50743c"/></g><path d="m50 56 4 10 11 2-9 7 2 11-9-6-10 5 3-11-8-8 11-1z" fill="#c39556"/><circle cx="79" cy="25" r="3" fill="#9ab471"/><circle cx="277" cy="188" r="4" fill="#c8a166"/><path d="m62 229 21-5 M250 30l8-6" stroke="#9ab471" stroke-width="3" stroke-linecap="round"/></svg>`}
function previousShell(body){return `<div class="app-shell"><aside class="sidebar" id="main-navigation" aria-label="Main navigation"><button class="mobile-close" aria-label="Close navigation" data-action="menu">×</button><div class="brand"><div class="brandmark">m</div><span>Malay<span>Mate</span></span></div><div class="brand-sub">MADE FOR YOUR EVERYDAY</div><div class="nav-group">${role==='admin'?'WORKSPACE':'YOUR LEARNING'}</div>${role==='admin'?[['dashboard','Overview','home'],['users','Students','users'],['content','Content studio','learn'],['assessments','Assessments','file'],['analytics','Learning analytics','progress'],['ml','Adaptive insights','review'],['adminfeedback','Student feedback','phrase'],['settings','Learning settings','settings']].map(a=>navItem(...a)).join(''):[['dashboard','Overview','home'],['modules','Learning path','learn'],['phrasebook','Phrasebook','phrase'],['reviews','Personalised review','review'],['progress','My progress','progress'],['achievements','Rewards & quests','award']].map(a=>navItem(...a)).join('')}<div class="nav-group">${role==='admin'?'':'YOUR SPACE'}</div>${role!=='admin'?navItem('profile','My profile','user')+navItem('feedback','Share feedback','phrase'):''}<div class="nav-foot"><div class="streak-note">${role==='admin'?'🌱 <b>Small steps. Real connections.</b><br>Shape learning around everyday student life.':`🌱 <b>A little practice goes a long way.</b><br>Keep growing, one phrase at a time.`}</div><div class="person"><div class="avatar">${role==='admin'?'AD':esc(state.profile.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</div><div><strong>${role==='admin'?'Administrator':esc(state.profile.name)}</strong><small>${role==='admin'?'Content & learning team':esc(state.profile.level)+' learner'}</small></div><button style="margin-left:auto;width:20px" title="Log out" aria-label="Log out" data-action="logout">${icon('logout')}</button></div></div></aside><div class="main-shell"><header class="topbar"><button class="mobile-toggle" aria-label="Open navigation" aria-controls="main-navigation" aria-expanded="false" data-action="menu">☰</button><span class="crumb">Your everyday Malay companion <span style="padding:0 12px">/</span> <b>${title()}</b></span><div class="top-actions">${role==='admin'?pill('Administrator','outline'):pill('🔥 '+streak()+' day streak','gold')+pill('✦ '+xp()+' XP')}<button class="avatar" data-action="nav:${role==='admin'?'settings':'profile'}" aria-label="${role==='admin'?'Learning settings':'Your profile'}">${role==='admin'?'AD':esc(state.profile.name[0])}</button></div></header><div class="demo-bar"><span><span class="status-dot"></span> FRONTEND PREVIEW · Data saved on this device</span><div class="demo-actions"><button class="text-btn" data-action="switch:${role==='admin'?'student':'admin'}">Preview ${role==='admin'?'student':'admin'}</button><a class="text-btn" href="MalayMate_Frontend_Project.zip" download>Download project</a></div></div><main class="page" id="main" tabindex="-1">${body}<footer class="footer"><span>AIU MalayMate · Practical Malay. Everyday confidence.</span><span>Learn a little. Connect a lot.</span></footer></main></div></div>`}
const head=(t,sub,action='')=>`<div class="page-head"><div><h1>${t}</h1><p>${sub}</p></div>${action}</div>`;
const stat=(n,label,i)=>`<div class="stat"><div class="stat-icon">${i}</div><div><strong>${n}</strong><small>${label}</small></div></div>`;
function moduleRow(m){return `<div class="card module-card"><div class="module-icon">${m.emoji}</div><div class="module-main"><h3>${esc(m.title)}</h3><p>${visibleLessons(m.id).length} short lessons · ${esc(m.level)}</p>${progress(modulePct(m.id))}<div class="row tiny space-sm"><span class="muted">${modulePct(m.id)}% complete</span><span>${modulePct(m.id)===100?'Completed':'Keep growing'}</span></div></div>${btn(icon('arrow'),'module:'+m.id,'secondary small','aria-label="Open '+esc(m.title)+'"')}</div>`}
function previousDashboard(){if(role==='admin')return adminDashboard();let first=visibleLessons(selectedModule).find(l=>!state.completed.includes(l.id))||allVisible().find(l=>!state.completed.includes(l.id));let recs=recommendations();return head(`Selamat datang, ${esc(state.profile.name.split(' ')[0])} <span style="font-size:27px">☀</span>`,'A little Malay today. A little more confidence tomorrow.',pill(state.profile.level+' · Your starting level','outline'))+`<section class="hero"><div class="hero-copy"><span class="eyebrow">YOUR NEXT EVERYDAY MOMENT</span><h2>A new language.<br>A world of connections.</h2><p>From your first greeting to your next campus conversation, let’s take the next step together.</p>${btn('Continue learning '+icon('arrow'),first?'lesson:'+first.id:'nav:modules','light')}</div><div class="hero-art">${art()}</div></section><div class="stats">${stat(xp(),'Total experience','✦')}${stat(streak()+' days','Current streak','🔥')}${stat(state.completed.filter(x=>allVisible().some(l=>l.id===x)).length,'Lessons completed','▤')}${stat(average()+'%','Assessment average','◷')}</div>${dashboardRewards()}<div class="grid-2"><section><div class="section-head"><h2>Keep your momentum</h2><button class="text-btn" data-action="nav:modules">View learning path ↗</button></div>${visibleModules().slice(0,3).map(moduleRow).join('')}<div class="card soft"><div class="row"><div><span class="eyebrow">WORDS FOR RIGHT NOW</span><h3 style="margin-top:12px">“Terima kasih.”</h3><small>Thank you. Two words, a meaningful connection.</small></div><button class="audio-btn" data-action="speak:Terima kasih" aria-label="Hear Terima kasih">${icon('audio')}</button></div><button class="text-btn space" data-action="nav:phrasebook">Explore your phrasebook ↗</button></div></section><aside><div class="section-head"><h2>Picked for your progress</h2>${pill('For you','purple')}</div>${recs.length?`<div class="rec">${pill(recs[0].priority+' priority','gold')}<h3>A little ${esc(recs[0].module.title.toLowerCase())} practice?</h3><p>${esc(recs[0].reason)}</p>${btn('Let’s practise '+icon('arrow'),'start-review:'+recs[0].module.id,'secondary')}</div>`:`<div class="card soft"><h3>${state.scenario==='cold'?'Let’s get to know you':'You’re making progress'}</h3><p class="muted">${state.scenario==='cold'?'Complete a quiz to receive a personalised review.':'Explore another lesson to keep your confidence growing.'}</p>${btn('Explore lessons','nav:modules','secondary')}</div>`}<div class="card"><div class="row"><h3 style="margin:0">Your growing habit</h3><span>🌱</span></div><p class="tiny muted space-sm">One learning activity a day makes a difference.</p><div class="week">${Array.from({length:7},(_,i)=>{let d=dayAgo(6-i);let label=new Date(d+'T12:00:00').toLocaleDateString('en',{weekday:'narrow'});return `<div class="day ${state.days.includes(d)?'done':''}">${label}<span>${state.days.includes(d)?'✓':i===6?'•':'·'}</span></div>`}).join('')}</div><div class="quote">“Sedikit-sedikit, lama-lama jadi bukit.”<small>Little by little, a little becomes a lot.</small></div></div>${!state.placement?`<div class="callout">New to Malay? Find a comfortable starting point.<br><button class="text-btn" data-action="nav:placement">Take the placement test ↗</button></div>`:''}</aside></div>`}
function previousModulesView(){return head('Your path to everyday Malay','Short lessons, practical phrases, real connections.',btn('Find my level','nav:placement','secondary'))+`<div class="tabs">${['All levels',...state.levels.filter(l=>l.status==='Published').sort((a,b)=>a.order-b.order).map(l=>l.id)].map(x=>`<button class="tab ${filterLevel===x?'active':''}" data-action="level-filter:${x}">${esc(x)}</button>`).join('')}</div><div class="grid-3">${visibleModules().filter(m=>filterLevel==='All levels'||m.level===filterLevel).map(m=>`<article class="card catalog-card"><div class="catalog-banner" style="background:${['#eaf0dc','#f3ead6','#e8edf2'][state.levels.findIndex(l=>l.id===m.level)%3]}"><span>${m.emoji}</span>${pill(m.level,'outline')}</div><div class="catalog-content"><h3>${esc(m.title)}</h3><p>${esc(m.description)}</p><div class="row tiny" style="margin-bottom:10px"><span>${visibleLessons(m.id).length} lessons · ~15 min</span><span>${modulePct(m.id)}%</span></div>${progress(modulePct(m.id))}${btn(modulePct(m.id)?'Continue module '+icon('arrow'):'Explore module '+icon('arrow'),'module:'+m.id,'secondary')}</div></article>`).join('')||'<div class="empty">No published modules at this level yet.</div>'}</div>`}
function moduleView(){let m=mod(selectedModule);return `<button class="back" data-action="nav:modules">${icon('back')} Back to topics</button>`+head(esc(m.title),esc(m.description),pill(m.level))+`<div class="grid-2"><div><div class="card nopad">${visibleLessons(m.id).map((l,i)=>`<div class="lesson-list"><div class="lesson-index">${state.completed.includes(l.id)?'✓':String(i+1).padStart(2,'0')}</div><div class="module-main"><h3>${esc(l.title)}</h3><p style="margin:0">${esc(l.type)} · ~5 minutes · ${state.completed.includes(l.id)?'Completed':state.lessonSteps[l.id]?'In progress':'Ready to start'}</p></div>${btn(state.completed.includes(l.id)?'Practise again':state.lessonSteps[l.id]?'Resume':'Start','lesson:'+l.id,'secondary small')}</div>`).join('')||'<div class="empty">Lessons are being prepared.</div>'}</div>${btn('Take topic quiz','start-quiz:'+m.id)} ${btn('Practise this topic','start-practice:'+m.id,'secondary')}</div><div><div class="card"><h3>Your module progress</h3><div class="metric-ring" style="--value:${modulePct(m.id)}%"><div><strong>${modulePct(m.id)}%</strong><small>completed</small></div></div><p class="tiny muted">Finish the lesson activities and pass the quiz to complete a lesson. You can come back and practise any time.</p></div><div class="card soft"><h3>What you’ll practise</h3><ul class="note-list"><li>Malay ↔ English words and phrases</li><li>Listening with a visible transcript</li><li>A short everyday dialogue</li><li>Putting a useful sentence together</li></ul></div></div></div>`}
function lessonView(){let l=lesson(selectedLesson),m=mod(l.moduleId),ps=state.phrases.filter(p=>p.moduleId===m.id&&p.status==='Published'),tabs=['Learn the words','Listen & read','Make a sentence','Take a short quiz'];if(!ps.length)return head('Lesson content unavailable','This lesson needs published phrase content before it can be previewed.',btn('Back to module','module:'+m.id));let current=ps[flash%ps.length],word=ps[(Number(l.order)-1)%ps.length],page='';if(lessonTab===0)page=`<div class="card"><div class="section-head"><h3>Tap a card to see its meaning</h3>${pill('Tap to flip','outline')}</div><button class="flashcard" data-action="flip"><span class="eyebrow">${flipped?'ENGLISH':'BAHASA MELAYU'}</span><strong>${esc(flipped?current.english:current.malay)}</strong><small>${flipped?esc(current.malay):'Tap this card to reveal the meaning'}</small></button><div class="row space"><button class="text-btn" data-action="flash-prev">← Previous</button><small>${flash+1} / ${ps.length}</small><button class="text-btn" data-action="flash-next">Next →</button></div></div><div class="card">${ps.map(p=>`<div class="vocab-row"><div><strong>${esc(p.malay)}</strong><small>${esc(p.english)}</small></div><button class="audio-btn" data-action="phrase-audio:${p.id}" aria-label="Listen to ${esc(p.malay)}">${icon('audio')}</button></div>`).join('')}</div>`;
if(lessonTab===1)page=`<div class="card"><span class="eyebrow">LISTEN & REPLAY</span><h2 style="margin-top:14px">${esc(word.malay)}</h2><p class="muted">${esc(word.english)}</p><div class="row"><div>${btn(icon('audio')+' Play / replay','phrase-audio:'+word.id,'secondary')}${btn('Pause / resume','pause-audio','secondary small')}${btn('Stop','stop-audio','secondary small')}</div></div><label class="field space">Playback speed<select id="audio-speed"><option value="1">Normal speed</option><option value="0.75">Slow · 0.75×</option></select></label><small>Listen to the recording or follow the transcript above. If audio is unavailable, ask your administrator to attach a Malay recording.</small></div><div class="card"><span class="eyebrow">IN A REAL CONVERSATION</span>${dialogueFor(m.id).map((d,i)=>`<div class="dialogue"><div class="avatar">${i%2?'B':'A'}</div><div class="bubble"><p>${esc(d[0])}</p><small>${esc(d[1])}</small><button class="text-btn" data-action="speak:${esc(d[0])}" aria-label="Hear dialogue line ${i+1}">Listen</button></div></div>`).join('')}<p class="tiny muted">${esc(sceneLabels[m.id]||m.title)} · Read each line, then practise with a partner.</p></div>`;
if(lessonTab===2){let words=word.malay.split(' ');page=`<div class="card"><span class="eyebrow">MAKE A SENTENCE</span><h2 style="margin:20px 0">${esc(word.english)}</h2><p class="muted">Select the Malay words in the correct order. Tap a selected word to remove it.</p><div class="answer-zone">${tokens.map((t,i)=>`<button class="token" data-action="remove-token:${i}">${esc(t.text)}</button>`).join('')}</div><div class="tokens">${words.map((w,i)=>({w,i})).reverse().filter(x=>!tokens.some(t=>t.index===x.i)).map(x=>`<button class="token" data-action="token:${x.i}">${esc(x.w)}</button>`).join('')}</div><div id="sentence-feedback" role="status"></div>${btn('Check sentence','check-sentence')}${btn('Clear','clear-sentence','secondary')}</div>`}
if(lessonTab===3)page=`<div class="card"><span class="eyebrow">CHECK WHAT YOU KNOW</span><h2 style="margin-top:15px">Ready for a short quiz?</h2><p>Answer a few questions about this lesson. After you finish, you can see your score and learn from each answer.</p><div class="callout">${state.config.complete==='Activities only'?'Completion requires all three activity sections.':`Complete all three activity sections and reach ${state.config.pass}% on the quiz.`} Practise again any section before you begin.</div><p class="tiny muted">Activities opened: ${[0,1,2].filter(t=>state.lessonSteps[l.id]?.visited?.includes(t)).length} / 3</p>${btn('Start quiz','start-lesson-quiz:'+l.id)}</div>`;
return `<div class="lesson-stage"><button class="back" data-action="module:${m.id}">← ${esc(m.title)}</button>`+head(esc(l.title),'Learn the words, try the activities, then take a short quiz.',pill(state.completed.includes(l.id)?'Completed':'In progress'))+`<div class="tabs">${tabs.map((t,i)=>`<button class="tab ${lessonTab===i?'active':''}" data-action="lesson-tab:${i}">${i+1}. ${t}</button>`).join('')}</div>${page}<div class="lesson-nav">${btn('← Previous','lesson-tab:'+Math.max(0,lessonTab-1),'secondary',lessonTab===0?'disabled':'')}<small>${lessonTab+1} of 4 sections</small>${btn(lessonTab===2?'Next: short quiz →':'Next section →','lesson-tab:'+Math.min(3,lessonTab+1),'',lessonTab===3?'disabled':'')}</div></div>`}
function phrasebook(){let ps=state.phrases.filter(p=>p.status==='Published'&&visibleModules().some(m=>m.id===p.moduleId)).filter(p=>phraseCategory==='All categories'||p.category===phraseCategory).filter(p=>!searchPhrase||(direction==='en'?p.english:direction==='ms'?p.malay:p.malay+' '+p.english).toLowerCase().includes(searchPhrase.toLowerCase()));return head('Words for everyday life','Find a word in Malay or English. Read its meaning, hear it, or open a lesson to practise.')+`<div class="filters"><input class="search" id="phrase-search" placeholder="Try ‘thank you’ or ‘terima kasih’" aria-label="Search phrases" value="${esc(searchPhrase)}"><select id="phrase-direction" aria-label="Search language">${[['both','Malay ↔ English'],['ms','Malay → English'],['en','English → Malay']].map(x=>`<option value="${x[0]}" ${direction===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select><select id="phrase-category" aria-label="Phrase category">${['All categories',...state.categories].map(c=>`<option ${c===phraseCategory?'selected':''}>${esc(c)}</option>`).join('')}</select></div><p class="tiny muted">${ps.length} published phrases · Malay and English meanings</p><div class="grid-equal">${ps.map(p=>`<article class="card"><div class="row start"><div><span class="eyebrow">${esc(p.category)}</span><h3 style="margin-top:14px;font-size:19px">${esc(p.malay)}</h3><p class="muted" style="margin-bottom:8px">${esc(p.english)}</p></div><button class="audio-btn" data-action="phrase-audio:${p.id}" aria-label="Listen to ${esc(p.malay)}">${icon('audio')}</button></div>${p.pronunciation?`<p class="tiny muted">Pronunciation guide: ${esc(p.pronunciation)}</p>`:''}<div class="callout" style="margin:12px 0;font-size:11px">${esc(p.example||'No example added yet.')}</div><div class="row"><small></small>${p.lessonId?`<button class="text-btn" data-action="lesson:${p.lessonId}">Practise ↗</button>`:''}</div></article>`).join('')||'<div class="card empty"><h3>No matching phrases yet</h3><p>Try a shorter word, switch the search language, or choose another category.</p></div>'}</div>`}
function makeQuestions(mid,type){let m=mod(mid),ps=state.phrases.filter(p=>p.moduleId===mid&&p.status==='Published');if(!ps.length)ps=state.phrases.filter(p=>p.status==='Published').slice(0,3);let p=ps[0],p2=ps[1]||p,p3=ps[2]||p;let base=[{id:mid+'-q1',type:'Multiple choice',text:`What does “${p.malay}” mean?`,options:[p.english,'Good night','Please wait','I do not understand'],correct:0,explanation:`“${p.malay}” means “${p.english}”.`,concept:mid+'-vocabulary',points:1},{id:mid+'-q2',type:'Listening',text:'Listen to the phrase. Choose its meaning.',audio:p2.malay,options:['See you tomorrow',p2.english,'I am hungry','Go straight ahead'],correct:1,explanation:`You heard “${p2.malay}”: ${p2.english}.`,concept:mid+'-listening',points:1},{id:mid+'-q3',type:'Written answer',text:`Write in Malay: “${p3.english}”`,correct:p3.malay,explanation:`The expected phrase is “${p3.malay}”. Capitalisation, punctuation and repeated spaces are ignored.`,concept:mid+'-sentence',points:1},{id:mid+'-q4',type:'Sentence building',text:`Build the Malay phrase: “${p.english}”`,words:p.malay.split(' '),correct:p.malay,explanation:`The correct word order is “${p.malay}”.`,concept:mid+'-sentence',points:1},{id:mid+'-q5',type:'Multiple choice',text:`Which phrase means “${p2.english}”?`,options:['Selamat malam','Saya tidak tahu',p2.malay,'Sila tunggu'],correct:2,explanation:`Use “${p2.malay}” in this situation.`,concept:mid+'-vocabulary',points:1}];if(type==='Placement'){base=[makeQuestions('greetings','Practice')[0],(makeQuestions('campus','Practice')[1]||makeQuestions('campus','Practice')[0]),(makeQuestions('food','Practice')[2]||makeQuestions('food','Practice')[0]),makeQuestions('shopping','Practice')[0],(makeQuestions('workplace','Practice')[3]||makeQuestions('workplace','Practice')[0])].map((q,i)=>({...q,id:'placement-q'+i}))}return [...base,...(state.extraQuestions[type==='Placement'?'placement':mid]||[])].filter(q=>!state.removedQuestions.includes(q.id)).map(q=>({...q,...state.questionEdits[q.id]}))}
function placementView(){let a=state.placement,days=a?Math.floor((new Date()-new Date(a.end))/86400000):999,eligible=!a||days>=state.config.retake;return head('Find the right place to start','Answer a few questions. We will suggest a level for you.')+`<div class="quiz-center"><div class="card"><span class="eyebrow">GETTING TO KNOW YOUR MALAY</span><h2 style="margin-top:18px">How much Malay do you know?</h2><p>Answer the placement questions covering greetings, campus, food, shopping and workplace phrases. You’ll try multiple choice, listening, a typed answer and sentence building. Allow about 5 minutes.</p><ul class="note-list"><li>Choose or enter one answer for every question.</li><li>You can return to earlier questions before submitting.</li><li>There is no time limit. Audio can be replayed.</li><li>Your score and suggested level appear after submission.</li></ul><div class="callout warning">Starting-level score bands: below ${state.config.band1}% → Foundation; ${state.config.band1}–${state.config.band2-1}% → Everyday; ${state.config.band2}% and above → Connections. All three remain beginner communication levels. You can retake this check after ${state.config.retake} days.</div>${a?`<div class="detail-grid"><div><small>Last score</small><strong>${a.score}%</strong></div><div><small>Assigned level</small><strong>${esc(a.level)}</strong></div><div><small>Completed</small><strong>${esc(a.date)}</strong></div></div><p class="tiny muted space">${eligible?'You may take the placement check again.':`Retake available after ${new Date(new Date(a.end).getTime()+state.config.retake*86400000).toLocaleDateString('en-GB')}. Continue learning in the meantime.`}</p>`:''}${btn(a?'Retake placement':'Find my level','begin:Placement','',eligible?'':'disabled')}</div><p class="tiny muted">This prototype records attempts in this browser only. Your placement helps suggest where to begin; all published lessons remain available.</p></div>`}
function startQuiz(mid,type='Quiz',lid=null,definitionId=null){let def=definitionId?state.assessments.find(a=>a.id===definitionId):type==='Placement'?state.assessments.find(a=>a.id==='placement'):(state.assessments.find(a=>a.moduleId===mid&&a.type===type)||state.assessments.find(a=>a.moduleId===mid&&a.type==='Quiz'));if(def?.status!=='Published'){toast('This assessment is unpublished. Ask the administrator to publish it.');return}if(type==='Placement'&&state.placement&&(new Date()-new Date(state.placement.end))/86400000<state.config.retake){toast('Placement retake is not available yet.');return}quiz={id:'attempt-'+Date.now(),moduleId:mid,type,lessonId:lid,questions:makeQuestions(mid,type),answers:{},times:{},index:0,start:new Date().toISOString(),questionStart:Date.now(),pass:def?.pass??state.config.pass};view='quiz';render()}
const normal=s=>String(s??'').toLowerCase().replace(/[.,!?;:]/g,'').trim().replace(/\s+/g,' ');
function quizView(){let q=quiz.questions[quiz.index],a=quiz.answers[q.id],count=quiz.questions.filter(q=>quiz.answers[q.id]!==undefined&&String(quiz.answers[q.id]).trim()!=='').length;return `<div class="quiz-center"><button class="back" data-action="nav:modules">← Leave assessment</button>`+head(quiz.type==='Placement'?'Your starting point':`${esc(mod(quiz.moduleId).title)} · ${quiz.type.toLowerCase()}`,`Question ${quiz.index+1} of ${quiz.questions.length} · No time limit`,pill(q.type,'purple'))+`<div class="quiz-progress">${quiz.questions.map((x,i)=>`<button class="${quiz.answers[x.id]!==undefined?'answered':''} ${i===quiz.index?'current':''}" data-action="quiz-go:${i}" aria-label="Go to question ${i+1}"></button>`).join('')}</div><div class="card"><div class="row"><span class="eyebrow">${q.points} POINT${q.points===1?'':'S'}</span><small>${count} / ${quiz.questions.length} answered</small></div><h2>${esc(q.text)}</h2>${q.type==='Listening'?`<div style="margin-bottom:20px">${btn(icon('audio')+' Play audio','speak:'+q.audio,'secondary')}${btn('Pause / resume','pause-audio','secondary small')}<details class="space-sm"><summary class="tiny">Show transcript (accessibility)</summary><p>${esc(q.audio)}</p></details></div>`:''}${q.options?q.options.map((x,i)=>`<button class="quiz-option ${a===i?'chosen':''}" data-action="answer:${i}" aria-pressed="${a===i}"><span class="letter">${'ABCD'[i]}</span>${esc(x)}</button>`).join(''):q.type==='Sentence building'?`<div class="answer-zone">${(Array.isArray(a)?a:[]).map((x,i)=>`<button class="token" data-action="quiz-token-remove:${i}">${esc(q.words[x])}</button>`).join('')}</div><div class="tokens">${q.words.map((w,i)=>({w,i})).reverse().filter(x=>!(a||[]).includes(x.i)).map(x=>`<button class="token" data-action="quiz-token:${x.i}">${esc(x.w)}</button>`).join('')}</div>`:`<label class="field">Your Malay answer<input id="written-answer" autocomplete="off" placeholder="Type your answer here" value="${esc(a||'')}"></label><p class="tiny muted">Use the phrase you learned. Use the words from the lesson.</p>`}</div><div class="lesson-nav">${btn('← Previous','quiz-go:'+Math.max(0,quiz.index-1),'secondary',quiz.index===0?'disabled':'')}<small>Answers saved for this attempt</small>${quiz.index<quiz.questions.length-1?btn('Next →','quiz-go:'+(quiz.index+1)):btn('Finish quiz','confirm-submit')}</div></div>`}
function recordQuestionTime(){let q=quiz.questions[quiz.index];quiz.times[q.id]=(quiz.times[q.id]||0)+(Date.now()-quiz.questionStart);quiz.questionStart=Date.now()}
function submitQuiz(){if(!quiz)return;let rewardStart=xp(),badgesBefore=[...state.earned],levelBefore=xpLevel().number;recordQuestionTime();let responses=quiz.questions.map(q=>{let selected=quiz.answers[q.id],answer=q.options?q.options[selected]:(q.type==='Sentence building'?(selected||[]).map(i=>q.words[i]).join(' '):selected||'');let correct=q.options?selected===q.correct:normal(answer)===normal(q.correct);return {questionId:q.id,concept:q.concept,text:q.text,type:q.type,audio:q.audio,selectedOption:q.options?selected:null,answerText:answer,correctAnswer:q.options?q.options[q.correct]:q.correct,isCorrect:correct,points:q.points,earned:correct?q.points:0,explanation:q.explanation,responseTime:Math.round((quiz.times[q.id]||0)/1000)}});let total=responses.reduce((a,b)=>a+b.points,0),points=responses.reduce((a,b)=>a+b.earned,0),score=Math.round(points/total*100),end=new Date().toISOString();let a={id:quiz.id,type:quiz.type,moduleId:quiz.moduleId,lessonId:quiz.lessonId,score,correct:points,total,date:today(),start:quiz.start,end,status:'Completed',responses};if(a.type==='Placement'){a.level=score<state.config.band1?'Foundation':score<state.config.band2?'Everyday':'Connections';state.placement=a;state.profile.level=a.level;let u=state.users.find(u=>u.id===state.activeStudentId);if(u)u.level=a.level}state.attempts.push(a);award('assessment:'+a.type+':'+a.moduleId+':'+today(),a.type==='Review'?state.config.reviewXP:state.config.quizXP,a.type+' submitted');let ls=a.lessonId;if(ls){let visited=state.lessonSteps[ls]?.visited||[];if(visited.length===3&&(state.config.complete==='Activities only'||score>=quiz.pass)){if(!state.completed.includes(ls))state.completed.push(ls);award('lesson:'+ls,state.config.lessonXP,lesson(ls).title+' completed')}}syncBadges();result={...a,rewardXP:xp()-rewardStart,newBadges:state.earned.filter(id=>!badgesBefore.includes(id)),levelUp:xpLevel().number>levelBefore,passed:score>=quiz.pass,pass:quiz.pass,lessonCompleted:ls&&state.completed.includes(ls)};quiz=null;save();closeModal();view='result';render();window.scrollTo(0,0)}
function resultView(){if(!result)return head('No result selected','Choose an assessment from your history.',btn('My progress','nav:progress'));let r=result;return `<div class="quiz-center">${resultRewardPanel(r)}`+head(r.type==='Placement'?'Here is your suggested level':'Your quiz results','Check your score and learn from your answers.')+`<div class="card" style="text-align:center">${pill(r.type==='Placement'?'Level assigned':r.passed?'Passed':'Keep practising',r.passed?'':'gold')}<div class="result-score">${r.score}<span style="font-size:28px">%</span></div><p class="muted">${r.correct} / ${r.total} points · ${r.type==='Placement'?esc(r.level):`Pass mark ${r.pass||state.config.pass}%`}</p>${r.type==='Placement'?`<p>Your recommended starting level: <b>${esc(r.level)}</b></p>`:''}${r.lessonId?`<div class="callout">${r.lessonCompleted?'Lesson completed. Its completion XP is awarded only once.':'Lesson remains in progress. Visit all activity sections and meet the configured completion rule.'}</div>`:''}<p class="tiny muted">Completed ${new Date(r.end).toLocaleString('en-GB')}</p><div class="row" style="justify-content:center;flex-wrap:wrap">${btn('Continue learning','nav:modules')}${r.type!=='Placement'?btn('Practise this topic','start-review:'+r.moduleId,'secondary'):''}${btn('View progress','nav:progress','secondary')}</div></div><div class="card"><h3>Your answers explained</h3>${r.responses.length?r.responses.map((a,i)=>`<div class="result-review ${a.isCorrect?'':'wrong'}"><strong>${i+1}. ${esc(a.text)} ${a.isCorrect?'✓':'· Keep practising'}</strong><p>Your answer: ${esc(a.answerText)}</p><p><b>Expected:</b> ${esc(a.correctAnswer)}</p><p class="muted">${esc(a.explanation)}</p><small>${a.earned} / ${a.points} points · ${a.responseTime} seconds</small></div>`).join(''):'<p class="muted">This sample shows a score only. Finish a new quiz to see your answers and explanations.</p>'}</div></div>`}
function previousReviewsView(){let rs=recommendations();return head('A little practice, just for you','Practise again the topics that could use a little more confidence.')+`<div class="callout purple">${state.scenario==='ml'?'Illustrative ML-output scenario: probabilities and model identifiers are sample values, not live predictions.':state.scenario==='unavailable'?'The ML service is unavailable in this scenario. A transparent score-based fallback keeps review available.':'Reviews are suggested from your latest topic score. This preview uses score rules; ML recommendations will be connected during backend integration.'}</div>${!rs.length?`<div class="card empty"><h3>${state.scenario==='cold'?'Let’s learn about your starting point':'No pending reviews'}</h3><p>${state.scenario==='cold'?'Complete an assessment before personalised review is generated.':'Your latest assessed topics meet the pass threshold. Explore something new.'}</p>${btn('Explore learning path','nav:modules')}</div>`:`<div class="grid-equal">${rs.map(r=>`<div class="card"><div class="row">${pill(r.priority+' priority',r.priority==='High'?'gold':'purple')}${pill('Pending','outline')}</div><h2 style="margin-top:20px">${esc(r.module.title)}</h2><p class="muted">${esc(r.reason)}</p><div class="detail-grid"><div><small>Latest score</small><strong>${r.attempt.score}%</strong></div><div><small>Target</small><strong>${state.config.pass}%</strong></div><div><small>Next activity</small><strong>5-question review</strong></div></div><div class="row space">${btn('Begin review '+icon('arrow'),'start-review:'+r.module.id)}<button class="text-btn" data-action="module:${r.module.id}">Practise again lesson</button></div></div>`).join('')}</div>`}<div class="card"><h3>How your review changes</h3><p class="muted">Completing a review records a new score and updates your topic mastery. A topic stops appearing in the pending list when the latest score reaches ${state.config.pass}%. If it remains below the threshold, a fresh review stays available. Your previous attempts remain available in My progress.</p></div>`}
function previousProgressView(){return head('Look how far you’ve come','Every phrase, every attempt, every small step counts.')+`<div class="stats">${stat(allPct()+'%','Learning path complete','▤')}${stat(average()+'%','Assessment average','◷')}${stat(state.attempts.length,'Assessments completed','✓')}${stat(recommendations().length,'Pending reviews','↺')}</div><div class="grid-equal"><div class="card"><h3>Topic mastery</h3><p class="tiny muted">Your latest topic assessment score. Confident: ≥${state.config.mastery}%; developing: ${state.config.pass}–${state.config.mastery-1}%; otherwise needs practice.</p>${visibleModules().map(m=>`<div style="margin:19px 0"><div class="row tiny" style="margin-bottom:9px"><b>${esc(m.title)}</b><span>${latestFor(m.id)?mastery(m.id)+'% · '+(mastery(m.id)>=state.config.mastery?'Confident':mastery(m.id)>=state.config.pass?'Still learning':'Keep practising'):'Not assessed'}</span></div>${progress(mastery(m.id))}</div>`).join('')}</div><div><div class="card"><h3>Concept evidence</h3><p class="tiny muted">See which skills you answered correctly in your quizzes.</p>${conceptEvidence()}</div><div class="card"><h3>Lessons you’ve completed</h3>${state.completed.map(id=>`<div class="vocab-row"><div><strong style="font-size:12px">${esc(lesson(id).title)}</strong><small>${esc(mod(lesson(id).moduleId).title)}</small></div><button class="text-btn" data-action="lesson:${id}">Practise again</button></div>`).join('')}</div></div></div><div class="section-head"><h2>Assessment history</h2></div>${attemptTable(state.attempts)}`}
function conceptEvidence(){let groups={};state.attempts.flatMap(a=>a.responses).forEach(r=>{groups[r.concept]??={n:0,ok:0};groups[r.concept].n++;if(r.isCorrect)groups[r.concept].ok++});return Object.keys(groups).length?Object.entries(groups).map(([k,v])=>`<div class="vocab-row"><div><b>${esc(k.replace(/-vocabulary$/,' · Word meanings').replace(/-listening$/,' · Listening').replace(/-sentence$/,' · Sentences').replaceAll('-',' '))}</b><small>${v.ok} / ${v.n} responses correct</small></div>${pill(Math.round(v.ok/v.n*100)+'%')}</div>`).join(''):'<div class="empty">Complete a new assessment to see vocabulary, listening and sentence evidence.</div>'}
function attemptTable(as){return `<div class="table-wrap"><table><thead><tr><th>Assessment</th><th>Score</th><th>Status</th><th>Completed</th><th>Review</th></tr></thead><tbody>${as.slice().reverse().map(a=>`<tr><td>${esc(mod(a.moduleId).title)}<small>${esc(a.type)} </small></td><td><b>${a.score}%</b><small>${a.correct} / ${a.total} points</small></td><td>${pill('Completed')}</td><td>${esc(a.date)}</td><td>${btn('View answers','attempt:'+a.id,'secondary small')}</td></tr>`).join('')}</tbody></table></div>`}

function profileView(){let p=state.profile;return head('Your profile','Update your name, details and learning goal.')+`<div class="grid-2"><form class="card" id="profile-form" data-old-email="${esc(p.email)}"><div class="form-grid">${input('Full name','name',p.name,'text',true)}${input('Email address','email',p.email,'email',true)}${input('Student ID','studentId',p.studentId)}${input('Nationality','nationality',p.nationality)}<label class="field full">Your learning goal<textarea name="goal">${esc(p.goal)}</textarea></label></div><p class="tiny muted space">Your level and learning points update as you learn. Profile changes in this preview stay on this device.</p>${btn('Save profile','submit-profile')}</form><div><div class="card soft"><h3>My starting point</h3><p>${esc(p.level)} learner</p>${btn('View placement test','nav:placement','secondary')}</div><div class="card"><h3>About your information</h3><p class="tiny muted">This preview uses sample accounts. Your sample details and progress are saved only in this browser.</p>${btn('Add MalayMate to your device','install-app','secondary')}${btn('Sign out','logout','secondary')}</div></div></div>`}
function feedbackView(){return head('Tell us what you think','Was something helpful or confusing? Tell us so we can improve it.')+`<div class="grid-2"><form class="card" id="feedback-form"><h3>How was your learning experience?</h3><div class="space-sm" role="group" aria-label="Rate from one to five">${[1,2,3,4,5].map(i=>`<button type="button" class="feedback-star" data-action="rating:${i}" aria-label="${i} stars" aria-pressed="${i===feedbackRating}">${i<=feedbackRating?'★':'☆'}</button>`).join('')}</div><p class="tiny muted">${feedbackRating} of 5</p><label class="field space">What would you like us to know? (optional)<textarea name="comment" maxlength="2000" placeholder="For example, more campus dialogues or slower audio…"></textarea></label>${btn('Send feedback','submit-feedback')}<p class="tiny muted space-sm">Saved with your demo name and submission date. Visible in the administrator’s feedback inbox.</p></form><div class="card"><h3>Your recent feedback</h3>${state.feedback.filter(f=>f.userId?f.userId===state.activeStudentId:f.name===state.profile.name).map(f=>`<div class="vocab-row"><div><b>${'★'.repeat(f.rating)}</b><p class="tiny">${esc(f.comment||'Rating only')}</p><small>${f.date}</small></div>${pill(f.status)}</div>`).join('')||'<p class="muted">No feedback yet. We’d like to hear from you.</p>'}</div></div>`}
function adminDashboard(){return head('A clearer picture of learning','Manage practical content and support each learner’s next step.',btn(icon('plus')+' Create content','edit:Modules:new'))+`<div class="callout">Fictional demonstration cohort: ${state.users.length} student accounts. Counts and records reflect the fictional accounts and activity saved on this device.</div><div class="stats">${stat(state.users.filter(u=>u.status==='Active').length,'Active sample students','♙')}${stat(visibleModules().length,'Published modules','▤')}${stat(cohortAttempts().length,'Assessments completed','✓')}${stat(state.feedback.filter(f=>f.status==='New').length,'Feedback to review','☏')}</div><div class="grid-2"><div><div class="section-head"><h2>Content at a glance</h2><button class="text-btn" data-action="nav:content">Open content studio ↗</button></div><div class="table-wrap"><table><thead><tr><th>Learning content</th><th>Published</th><th>Draft / unpublished</th></tr></thead><tbody>${[['Levels',state.levels],['Modules',state.modules],['Lessons',state.lessons],['Phrase entries',state.phrases],['Assessments',state.assessments]].map(([n,ls])=>`<tr><td>${n}</td><td>${ls.filter(x=>x.status==='Published').length}</td><td>${ls.filter(x=>x.status!=='Published').length}</td></tr>`).join('')}</tbody></table></div><div class="section-head space"><h2>Recent assessment activity</h2></div>${attemptTable(cohortAttempts().slice(-4))}</div><aside><div class="rec">${pill('Learning support','purple')}<h3>${recommendations().length} topics could use another look</h3><p>Review the performance evidence and recommendation reason before changing the learning policy.</p>${btn('View adaptive insights','nav:ml','secondary')}</div><div class="card"><h3>Learning operations</h3><ul class="note-list"><li>Review bilingual phrases and pronunciation audio with a language reviewer.</li><li>Keep scoring, progression and reward settings consistent.</li><li>Validate branding and campus communication with CCPC.</li></ul>${btn('Manage badges','open-badges','secondary small')}</div></aside></div>`}
function usersView(){return head('Students & access','Search accounts, inspect individual progress, and manage demo access.')+`<div class="filters"><input class="search" id="user-search" placeholder="Search name, email or student ID" aria-label="Search students"><select id="user-status" aria-label="Account status"><option>All statuses</option><option>Active</option><option>Suspended</option></select></div><div id="user-results">${userTable()}</div><p class="tiny muted space">Suspended accounts are blocked by the demo sign-in flow. Production authorization, session invalidation and permission checks require server enforcement.</p>`}
function userTable(q='',status='All statuses'){let us=state.users.filter(u=>(u.name+' '+u.email+' '+u.studentId).toLowerCase().includes(q.toLowerCase())&&(status==='All statuses'||u.status===status));return `<div class="table-wrap"><table><thead><tr><th>Student</th><th>Starting level</th><th>Status</th><th>Actions</th></tr></thead><tbody>${us.map(u=>`<tr><td><b>${esc(u.id==='u1'?state.profile.name:u.name)}</b><small>${esc(u.email)} · ${esc(u.studentId)}</small></td><td>${esc(u.id==='u1'?state.profile.level:u.level)}</td><td>${pill(u.status,u.status==='Suspended'?'red':'')}</td><td>${btn('View progress','user-detail:'+u.id,'secondary small')}${btn(u.status==='Active'?'Suspend':'Reactivate','user-status:'+u.id,u.status==='Active'?'danger small':'secondary small')}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">No matching students. Try another search.</td></tr>'}</tbody></table></div>`}
function collection(t){return ({Levels:state.levels,Modules:state.modules,Lessons:state.lessons,Phrases:state.phrases,Categories:state.categories,Badges:state.badgeDefs,Assessments:state.assessments})[t]}
function contentView(){return head('Content that connects','Create, order and publish bilingual lessons and practical phrase support.',btn(icon('plus')+' Add '+contentTab.slice(0,-1),'edit:'+contentTab+':new'))+`<div class="tabs">${['Levels','Modules','Lessons','Phrases','Categories','Badges'].map(t=>`<button class="tab ${contentTab===t?'active':''}" data-action="content-tab:${t}">${t}</button>`).join('')}</div><div class="callout">Draft and unpublished content is hidden from student browsing and search. A published lesson also needs a published module and level. Changes here update the same student preview immediately.</div><div class="filters"><input class="search" id="content-search" placeholder="Search ${contentTab.toLowerCase()}" aria-label="Search content"></div><div id="content-results">${contentTable()}</div>`}
function contentTable(q=''){let ls=collection(contentTab).filter(x=>JSON.stringify(x).toLowerCase().includes(q.toLowerCase()));if(contentTab==='Categories')return `<div class="table-wrap"><table><thead><tr><th>Category</th><th>Entries</th><th>Actions</th></tr></thead><tbody>${ls.map(c=>`<tr><td>${esc(c)}</td><td>${state.phrases.filter(p=>p.category===c).length}</td><td>${btn('Edit','edit:Categories:'+state.categories.indexOf(c),'secondary small')}${btn('Remove','delete:Categories:'+state.categories.indexOf(c),'danger small')}</td></tr>`).join('')}</tbody></table></div>`;return `<div class="table-wrap"><table><thead><tr><th>${contentTab==='Phrases'?'Malay & English':'Title'}</th><th>Context / order</th><th>Status</th><th>Actions</th></tr></thead><tbody>${ls.map(x=>`<tr><td><b>${esc(x.title||x.malay)}</b><small>${esc(x.english||x.description||x.concept||x.type||'')}</small></td><td>${esc(x.moduleId?mod(x.moduleId).title:x.level||x.category||x.condition||'')}<small>${x.order?'Display order '+x.order:x.lessonId?'Lesson: '+x.lessonId:''}</small></td><td>${pill(contentTab==='Badges'?(x.active?'Active':'Inactive'):x.status,x.status==='Draft'?'gold':'')}</td><td>${btn('Edit','edit:'+contentTab+':'+x.id,'secondary small')}${contentTab!=='Badges'?btn(x.status==='Published'?'Unpublish':'Publish','publish:'+contentTab+':'+x.id,'secondary small'):''}${btn('Remove','delete:'+contentTab+':'+x.id,'danger small')}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">No matching content.</td></tr>'}</tbody></table></div>`}
function input(label,name,value='',type='text',required=false,extra=''){return `<label class="field">${label}<input type="${type}" name="${name}" value="${esc(value)}" ${required?'required':''} ${extra}></label>`}
function selectField(label,name,options,value='',extra=''){return `<label class="field">${label}<select aria-label="${esc(label)}" name="${name}" ${extra}>${options.map(o=>{let v=typeof o==='string'?o:o.value,t=typeof o==='string'?o:o.label;return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`}).join('')}</select></label>`}
function textarea(label,name,value='',required=false){return `<label class="field full">${label}<textarea name="${name}" ${required?'required':''}>${esc(value)}</textarea></label>`}
function openEditor(type,id){let x=id==='new'?{}:type==='Categories'?{title:state.categories[Number(id)]}:collection(type).find(x=>x.id===id);if(!x)return;let fields='',status=()=>selectField('Publication status','status',['Draft','Published','Unpublished'],x.status||'Draft'),modules=()=>selectField('Parent module','moduleId',state.modules.map(m=>({value:m.id,label:m.title})),x.moduleId||state.modules[0].id),lessons=()=>selectField('Linked lesson','lessonId',[{value:'',label:'No lesson link'},...state.lessons.map(l=>({value:l.id,label:mod(l.moduleId).title+' / '+l.title}))],x.lessonId||'');if(type==='Levels')fields=input('Level title','title',x.title,'text',true)+input('Display order','order',x.order||state.levels.length+1,'number',true,'min="1"')+textarea('Description','description',x.description)+status();if(type==='Modules')fields=input('Module title','title',x.title,'text',true)+selectField('Learning level','level',state.levels.map(l=>({value:l.id,label:l.title})),x.level||state.levels[0].id)+input('Display order','order',x.order||state.modules.length+1,'number',true,'min="1"')+input('Module symbol / emoji','emoji',x.emoji||'▤')+textarea('Description','description',x.description)+status();if(type==='Lessons')fields=input('Lesson title','title',x.title,'text',true)+modules()+selectField('Primary lesson type','type',['Vocabulary','Listening','Sentence building','Dialogue'],x.type||'Vocabulary')+input('Display order','order',x.order||1,'number',true,'min="1"')+input('Skill label','concept',x.concept||'','text',true)+status()+`<p class="tiny muted full">Bilingual teaching content, example sentences and audio are edited under Phrases. Link each phrase to this lesson and concept. The prototype renders activities from its module’s published phrase set.</p>`;if(type==='Phrases')fields=input('Malay phrase','malay',x.malay,'text',true)+input('English meaning','english',x.english,'text',true)+modules()+selectField('Phrase category','category',state.categories,x.category||state.categories[0])+lessons()+input('Skill label','concept',x.concept)+textarea('Example sentence','example',x.example)+input('Pronunciation guide (optional)','pronunciation',x.pronunciation)+status()+`<label class="field full">Pronunciation recording (optional, MP3 / WAV / OGG; max 2 MB)<input type="file" name="audioFile" accept="audio/mpeg,audio/wav,audio/ogg"></label><p class="tiny muted">${x.audio?'A recording is attached. A new upload replaces it.':'Without a recording, preview uses the browser speech voice.'} Verify translation and pronunciation before final publication.</p>`;if(type==='Categories')fields=input('Category title','title',x.title,'text',true);if(type==='Badges')fields=input('Badge name','title',x.title,'text',true)+input('Symbol / emoji','emoji',x.emoji||'✦')+textarea('Description','description',x.description)+selectField('Award condition','condition',['xp','lesson','streak','quiz','perfect','review','module','game'],x.condition||'xp')+input('XP threshold (for xp condition)','xp',x.xp||0,'number',true,'min="0"')+selectField('Activation','active',[{value:'true',label:'Active'},{value:'false',label:'Inactive'}],String(x.active??true))+`<p class="tiny muted">Set the required count for the selected condition. Perfect means a 100% assessment; module means all published lessons are complete. Each badge is awarded once per student.</p>`;if(type==='Assessments')fields=input('Assessment title','title',x.title,'text',true)+modules()+lessons()+selectField('Assessment type','type',['Quiz','Practice','Review','Placement'],x.type||'Quiz')+input('Passing score (%)','pass',x.pass??state.config.pass,'number',true,'min="0" max="100"')+status();openModal((id==='new'?'Add ':'Edit ')+type.slice(0,-1),`<form id="editor-form" data-type="${type}" data-id="${id}"><div class="form-grid">${fields}</div><p id="editor-error" class="tiny" style="color:var(--red)" role="alert"></p><div class="actions">${btn('Cancel','close','secondary','type="button"')}${btn('Save changes','submit-editor')}</div></form>`)}
async function submitEditor(){let f=$('#editor-form');if(!f.reportValidity())return;let type=f.dataset.type,id=f.dataset.id,vals=Object.fromEntries(new FormData(f)),col=collection(type);if(type==='Categories'){let title=vals.title.trim();if(!title){$('#editor-error').textContent='Enter a category name.';return}if(col.includes(title)&&col[Number(id)]!==title){$('#editor-error').textContent='This category already exists.';return}if(id==='new')col.push(title);else{let old=col[Number(id)];col[Number(id)]=title;state.phrases.forEach(p=>{if(p.category===old)p.category=title})}}else{let old=col.find(x=>x.id===id)||{};delete vals.audioFile;for(let n of ['order','pass','xp'])if(vals[n]!==undefined)vals[n]=Number(vals[n]);if(vals.target!==undefined)vals.target=Number(vals.target);if(vals.active!==undefined)vals.active=vals.active==='true';if(type==='Phrases'){let file=f.elements.audioFile.files[0];if(file){if(file.size>2*1024*1024){$('#editor-error').textContent='Please choose an audio recording smaller than 2 MB.';return}vals.audio=await new Promise(resolve=>{let r=new FileReader();r.onload=()=>resolve(r.result);r.readAsDataURL(file)})}if(vals.lessonId&&lesson(vals.lessonId).moduleId!==vals.moduleId){$('#editor-error').textContent='Choose a lesson from the selected module, or remove the lesson link.';return}}let item={...old,...vals,id:id==='new'?type.toLowerCase()+'-'+Date.now():id};if(type==='Modules'&&!item.phrases)item.phrases=[];if(id==='new')col.push(item);else col[col.findIndex(x=>x.id===id)]=item}try{save()}catch(e){toast('Browser storage is full. Use a smaller audio file.');return}closeModal();render();toast('Changes saved.')}
function assessmentView(){return head('Assessment studio','Manage placement, practice, quizzes and review checks.',btn(icon('plus')+' Add assessment','edit:Assessments:new'))+`<div class="callout">Sample quizzes contain 5 questions per module. Edit question text, types, correct answers, explanations, audio transcript and points. Student score calculation uses these edits.</div><div class="table-wrap"><table><thead><tr><th>Assessment</th><th>Type / context</th><th>Pass mark</th><th>Status</th><th>Actions</th></tr></thead><tbody>${state.assessments.map(a=>`<tr><td><b>${esc(a.title)}</b><small>${esc(a.lessonId||'Cross-topic placement')}</small></td><td>${a.type}<small>${esc(mod(a.moduleId).title)}</small></td><td>${a.pass}%</td><td>${pill(a.status)}</td><td>${btn('Questions','questions:'+a.id,'secondary small')}${btn('Edit','edit:Assessments:'+a.id,'secondary small')}${btn(a.status==='Published'?'Unpublish':'Publish','publish:Assessments:'+a.id,'secondary small')}${btn('Preview','preview-assessment:'+a.id,'secondary small')}</td></tr>`).join('')}</tbody></table></div>`}
function questionsModal(id){let a=state.assessments.find(x=>x.id===id);let qs=makeQuestions(a.moduleId,a.type);openModal(esc(a.title)+' · Questions',`<p class="tiny muted">Question bank preview. Changes apply to subsequent attempts; existing completed responses retain their saved answer evidence.</p>${qs.map((q,i)=>`<div class="vocab-row"><div><strong style="font-size:13px">${i+1}. ${esc(q.text)}</strong><small>${esc(q.type)} · ${q.points} point(s) · ${esc(q.concept)}</small></div>${btn('Edit','edit-question:'+a.id+':'+i,'secondary small')}${btn('Remove','remove-question:'+a.id+':'+q.id,'danger small')}</div>`).join('')}${btn('Add question','add-question:'+a.id,'secondary small')}`)}
function questionEditor(aid,index){let a=state.assessments.find(a=>a.id===aid),q=makeQuestions(a.moduleId,a.type)[index];openModal('Edit assessment question',`<form id="question-form" data-id="${q.id}" data-assessment="${aid}"><div class="form-grid">${selectField('Question type','type',['Multiple choice','Listening','Written answer','Sentence building'],q.type)}${input('Points','points',q.points,'number',true,'min="1" max="20"')}${textarea('Question text','text',q.text,true)}${textarea('Options, one per line (for choice/listening)','options',(q.options||[]).join('\n'))}${input('Correct option number (1–4)','correctOption',typeof q.correct==='number'?q.correct+1:1,'number',false,'min="1" max="4"')}${input('Written / sentence answer','correctText',typeof q.correct==='string'?q.correct:'')}${input('Audio transcript (for listening)','audio',q.audio||'')}${input('Concept identifier','concept',q.concept,'text',true)}${textarea('Answer explanation','explanation',q.explanation,true)}</div><p id="question-error" role="alert" class="tiny" style="color:var(--red)"></p><div class="actions">${btn('Cancel','close','secondary','type="button"')}${btn('Save question','submit-question')}</div></form>`)}
function analyticsView(){return head('Learning insights','Filter saved student activity and export the matching report.',btn('Export report CSV','export-analytics','secondary'))+`<div class="filters"><select id="analytics-student" aria-label="Filter student">${state.users.map(u=>`<option value="${u.id}" ${u.id===state.activeStudentId?'selected':''}>${esc(u.name)}</option>`).join('')}</select><select id="analytics-level" aria-label="Filter level"><option>All levels</option>${state.levels.map(l=>`<option>${esc(l.id)}</option>`).join('')}</select><select id="analytics-module" aria-label="Filter module"><option value="all">All modules</option>${state.modules.map(m=>`<option value="${m.id}">${esc(m.title)}</option>`).join('')}</select><select id="analytics-type" aria-label="Filter assessment"><option>All assessments</option>${['Placement','Practice','Quiz','Review'].map(t=>`<option>${t}</option>`).join('')}</select></div><div id="analytics-result">${analyticsResult(state.attempts)}</div>`}
function filteredAttempts(){let student=$('#analytics-student')?.value||state.activeStudentId,level=$('#analytics-level')?.value||'All levels',module=$('#analytics-module')?.value||'all',type=$('#analytics-type')?.value||'All assessments';return learnerData(student).attempts.filter(a=>(level==='All levels'||mod(a.moduleId).level===level)&&(module==='all'||a.moduleId===module)&&(type==='All assessments'||a.type===type))}

function analyticsResult(as){let avg=as.length?Math.round(as.reduce((s,a)=>s+a.score,0)/as.length):0;return `<div class="stats">${stat(as.length,'Completed attempts','✓')}${stat(avg+'%','Average score','◷')}${stat(as.reduce((s,a)=>s+a.responses.length,0),'Answers recorded','▤')}${stat(as.filter(a=>a.type==='Review').length,'Review attempts','↺')}</div>${as.length?`<div class="grid-equal"><div class="card"><h3>Topic performance</h3>${state.modules.filter(m=>as.some(a=>a.moduleId===m.id)).map(m=>{let rows=as.filter(a=>a.moduleId===m.id),v=Math.round(rows.reduce((s,a)=>s+a.score,0)/rows.length);return `<div class="space"><div class="row tiny" style="margin-bottom:8px"><b>${esc(m.title)}</b><span>${v}% · ${rows.length} attempts</span></div>${progress(v)}</div>`}).join('')}</div><div class="card"><h3>Recent score trend</h3><div class="timeline">${as.slice(-6).map(a=>`<div><b>${a.score}%</b><span style="height:${a.score*.8}px"></span><small>${esc(a.type)}</small></div>`).join('')}</div><p class="tiny muted">Descriptive sample analytics only. This chart is not evidence of learning improvement or model accuracy. Planned evaluation uses pre/post tests and a separate SUS assessment.</p></div></div>${attemptTable(as)}`:'<div class="card empty"><h3>No matching attempts</h3><p>Change the filters or complete an assessment as this learner.</p></div>'}`}
function mlView(){let rs=recommendations();return head('Why this review?','Trace the learning evidence and inspect the intended adaptive service boundary.')+`<div class="callout purple">ML integration is pending; this frontend displays score-based recommendations and labelled response scenarios. The default score rule updates from saved assessments.</div><div class="filters"><label class="field" style="margin:0">Demonstration scenario<select id="ml-scenario">${[['rules','Transparent score rule'],['ml','Illustrative ML response'],['unavailable','Service unavailable → fallback'],['cold','Insufficient learner data']].map(([v,t])=>`<option value="${v}" ${state.scenario===v?'selected':''}>${t}</option>`).join('')}</select></label></div>${rs.length?rs.map(r=>`<div class="card"><div class="row"><h3>${esc(state.profile.name)} · ${esc(r.module.title)}</h3>${pill(r.priority+' priority','gold')}</div><div class="detail-grid space"><div><small>Trigger attempt</small><strong>${esc(r.attempt.id)}</strong></div><div><small>Latest score</small><strong>${r.attempt.score}%</strong></div><div><small>Recommendation status</small><strong>Pending</strong></div><div><small>Recommended lesson</small><strong>${esc(visibleLessons(r.module.id)[0]?.title||'Lesson unavailable')}</strong></div><div><small>Model / source</small><strong>${state.scenario==='ml'?'RandomForest · illustrative-v0':'Score rule · prototype-v1'}</strong></div><div><small>Mistake probability</small><strong>${state.scenario==='ml'?'0.72 (illustrative)':'Not estimated by rule'}</strong></div></div><p class="space tiny"><b>Reason:</b> ${esc(r.reason)}</p><details><summary class="tiny">View proposed request / response contract</summary><pre>${esc(JSON.stringify({request:{user_id:'demo-u1',trigger_attempt_id:r.attempt.id,topic:r.module.id,quiz_score:r.attempt.score,mistakes:r.attempt.total-r.attempt.correct,attempt_count:state.attempts.filter(a=>a.moduleId===r.module.id).length,lesson_completion:modulePct(r.module.id),response_time_seconds:r.attempt.responses.reduce((s,a)=>s+a.responseTime,0)},response:{weak_topic:r.module.id,mistake_probability:state.scenario==='ml'?0.72:null,priority:r.priority,recommended_lesson_id:visibleLessons(r.module.id)[0]?.id,model_name:state.scenario==='ml'?'RandomForest':'score-rule',model_version:state.scenario==='ml'?'illustrative-v0':'prototype-v1',reason:r.reason,status:'pending'}},null,2))}</pre></details></div>`).join(''):'<div class="card empty"><h3>No recommendation available</h3><p>Insufficient data should prompt a placement check or normal lesson, rather than inventing a probability.</p></div>'}<div class="card"><h3>Proposed production sequence</h3><ol class="note-list"><li>Store the scored attempt and question responses.</li><li>Prepare validated learning features in the Laravel adaptive manager.</li><li>Call Python / FastAPI and run the selected scikit-learn model.</li><li>Persist prediction, model version, reason and trigger attempt.</li><li>Show pending recommendations in priority order.</li><li>After review, update mastery and recommendation status; retain history.</li></ol><p class="tiny muted">Compare Logistic Regression and Random Forest using an approved dataset and evaluation split. Choose based on measured results; no training results or accuracy claims are supplied here.</p></div>`}
function adminFeedback(){return head('Listen to your learners','Review student ratings and comments, then track the response status.')+`<div class="table-wrap"><table><thead><tr><th>Submitted by</th><th>Rating & comment</th><th>Status</th><th>Review</th></tr></thead><tbody>${state.feedback.slice().reverse().map(f=>`<tr><td><b>${esc(f.name)}</b><small>${esc(f.date)}</small></td><td>${'★'.repeat(f.rating)}<p style="margin:6px 0">${esc(f.comment||'Rating only')}</p></td><td>${pill(f.status)}</td><td><select data-feedback="${f.id}" aria-label="Review status for ${esc(f.name)}">${['New','In review','Resolved'].map(s=>`<option ${s===f.status?'selected':''}>${s}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div>`}
function settingsView(){let c=state.config;return head('Learning & reward settings','Configure placement, scoring, completion and student rewards.')+`<div class="callout">Changes apply to new learning activities. Completed attempts keep their recorded results.</div><form class="card" id="settings-form"><div class="form-grid">${input('Quiz passing score (%)','pass',c.pass,'number',true,'min="1" max="100"')}${input('Confident threshold (%)','mastery',c.mastery,'number',true,'min="1" max="100"')}${input('Everyday placement minimum (%)','band1',c.band1,'number',true,'min="1" max="99"')}${input('Connections placement minimum (%)','band2',c.band2,'number',true,'min="2" max="100"')}${input('Placement retake interval (days)','retake',c.retake,'number',true,'min="0" max="365"')}${selectField('Lesson completion rule','complete',['Activities + passing quiz','Activities only'],c.complete)}${input('XP per lesson completion','lessonXP',c.lessonXP,'number',true,'min="0" max="1000"')}${input('XP per topic / assessment type / day','quizXP',c.quizXP,'number',true,'min="0" max="1000"')}${input('XP per review assessment','reviewXP',c.reviewXP,'number',true,'min="0" max="1000"')}</div><p class="tiny muted space">Streaks use the Asia/Kuala_Lumpur calendar day. Only qualifying learning events count. They advance at most once a day; duplicate event keys and duplicate badges are ignored.</p><p id="settings-error" role="alert" class="tiny" style="color:var(--red)"></p>${btn('Save learning policy','submit-settings')}</form><div class="card"><h3>Preview data</h3><p class="muted">All changes are saved in this browser. Resetting restores the original fictional accounts and learning content.</p>${btn('Reset preview data','reset-demo','danger')}</div>`}
function previousAuthView(){return `<div class="auth-wrap"><div class="auth-story"><div class="brand"><div class="brandmark" style="background:#d9edb0;color:#214c39">m</div>MalayMate</div><h2>Learn a little.<br>Connect a lot.</h2><p>Practical Malay for your everyday moments at AIU and beyond.</p><div style="height:180px">${art()}</div><small style="color:#d2dfc3">Interactive prototype · Fictional accounts only</small></div><div class="auth-form"><div class="tabs">${['login','register'].map(t=>`<button class="tab ${authTab===t?'active':''}" data-action="auth-tab:${t}">${t==='login'?'Sign in':'Create account'}</button>`).join('')}</div><h1>${authTab==='login'?'Welcome back':'Your journey starts here'}</h1><p class="tiny muted">${authTab==='login'?'Sign in with a sample account to explore.':'Try registration using fictional details.'}</p><form id="auth-form">${authTab==='register'?input('Full name','name','','text',true)+input('Student ID (optional)','studentId')+input('Nationality (optional)','nationality'):''}${input('Email address','email',authTab==='login'?'student@malaymate.demo':'','email',true)}${input('Password','password','','password',true,'minlength="8" autocomplete="off"')}${authTab==='register'?input('Confirm password','confirm','','password',true,'minlength="8" autocomplete="off"'):''}<p id="auth-error" role="alert" class="tiny" style="color:var(--red)"></p>${btn(authTab==='login'?'Sign in':'Create sample account','submit-auth')}<p class="tiny muted space">Demo password: <b>demo1234</b><br>Student: student@malaymate.demo<br>Admin: admin@malaymate.demo<br>Suspended: suspended@malaymate.demo</p><p class="tiny muted">No passwords are saved. Each student has separate learning progress on this device. For this frontend demonstration, all registered accounts use demo1234 on later sign-ins. This is a sign-in simulation.</p></form></div></div>`}
